@startuml

class SensorController {
  + sensorData : float
  + login(username, password) : boolean
  + queryValues() : float
  + configureSensor() : void
}

class Apartment {
  + address : string
}

class Room {
  + description : string
}

class Inhabitant {
  + username : string
  + password : string
  + isAdmin : boolean
}

abstract class Sensor {
  + vendorId : string
  + description : string
  + unit : Unit
  + threshold : float
}

class TemperatureSensor {
  + minValue : float
  + maxValue : float
}

class PowerSensor {
  + totalConsumption : float
}

class SensorValue {
  + timestamp : datetime
  + value : float
}

enum Unit {
  CELSIUS
  WATT
}

class EMonitor {}

Apartment "1" *-- "2..*" Room
Room "1" *-- "1..*" Sensor
Apartment "1" *-- "1..*" Inhabitant
Inhabitant "1..*" -- "1" Apartment
Sensor "1" *-- "1..*" SensorValue
Sensor "1" *-- "1" Room
SensorController "1" *-- "1" Apartment
SensorController "1" *-- "1..*" Sensor
Inhabitant "1..*" -- "1" SensorController : queries
EMonitor ..> SensorController : sendsAlert
EMonitor ..> Sensor : checksThreshold

Sensor --|> Sensor
TemperatureSensor --|> Sensor
PowerSensor --|> Sensor

@enduml

